import { stdout } from std.io;
class Node {
    v: Int32;
    next: Node?;
    construct(v: Int32) { this.v = v; this.next = null; }
}
fn main(): Void {
    mut a = Node(1);
    a.next = a;
    mut b = a.clone();
    stdout.println(b is a);
    stdout.println(b.next is b);
    stdout.println(b.next is a);
    b.v = 7;
    stdout.println(a.v);
}
